export type NativePlan = NativePlan_Serialize | NativePlan_Deserialize;

/**  The exact commands a native install runs, as shown in the consent dialog (passwords masked). */
export type NativePlan_Deserialize = {
    /**  winget, brew, apt-get, dnf, pacman or zypper; `None` when no supported one was found. */
    manager?: string | null;
    commands: string[];
    /**  The SQL run as the server admin to create the database and user (password masked). */
    setupSql: string;
    /**  True when a command asks for administrator rights (UAC, pkexec). */
    elevated: boolean;
    /**  False when QueryCraft can't run this safely here: `commands` are then manual steps. */
    supported: boolean;
    /**  Whether the admin password field applies (the installer sets it). */
    needsRootPassword: boolean;
    service?: string | null;
    notes: string[];
    /**  Sent back in `LocalRequest::consent`; ties the approval to these exact commands. */
    consentToken: string;
    /**  What to run to uninstall it later (QueryCraft doesn't uninstall). */
    uninstall?: string | null;
};

/**  The exact commands a native install runs, as shown in the consent dialog (passwords masked). */
export type NativePlan_Serialize = {
    /**  winget, brew, apt-get, dnf, pacman or zypper; `None` when no supported one was found. */
    manager: string | null;
    commands: string[];
    /**  The SQL run as the server admin to create the database and user (password masked). */
    setupSql: string;
    /**  True when a command asks for administrator rights (UAC, pkexec). */
    elevated: boolean;
    /**  False when QueryCraft can't run this safely here: `commands` are then manual steps. */
    supported: boolean;
    /**  Whether the admin password field applies (the installer sets it). */
    needsRootPassword: boolean;
    service: string | null;
    notes: string[];
    /**  Sent back in `LocalRequest::consent`; ties the approval to these exact commands. */
    consentToken: string;
    /**  What to run to uninstall it later (QueryCraft doesn't uninstall). */
    uninstall: string | null;
};

export type Os = 'windows' | 'macos' | 'linux';

/**  How a local database is provided. */
export type Provider =
    /**  A container QueryCraft creates and labels. */
    | 'docker'
    /**  A server installed with the OS package manager, after the user approved the commands. */
    | 'native'
    /**  A SQLite file in the app data directory. */
    | 'file';

export type QueryOutput = {
    columns: ResultColumn[];
    /**
     *  Every cell as text, `null` for SQL NULL. Text keeps big integers, decimals and
     *  timestamps exact; a JS number would round anything past 2^53.
     */
    rows: (string | null)[][];
    /**  More than `MAX_ROWS` rows came back; `rows` holds the first `MAX_ROWS`. */
    truncated: boolean;
    /**  For a SELECT, the total row count; otherwise rows inserted/updated/deleted. */
    rowsAffected: number;
    elapsedMs: number;
};

export type ResultColumn = {
    name: string;
    /**  The database's own type name, e.g. `INT4` or `TEXT`. Empty when SQLite has none. */
    typeName: string;
    /**  How the UI should align and size the column. */
    kind: ColumnKind;
};

export type SampleOutcome = SampleOutcome_Serialize | SampleOutcome_Deserialize;

export type SampleOutcome_Deserialize = {
    instance: LocalInstance_Deserialize;
    starterSql: string;
};

export type SampleOutcome_Serialize = {
    instance: LocalInstance_Serialize;
    starterSql: string;
};

export type SampleState = 'off' | 'loaded' | 'failed';

/**  A `ConnectRequest` minus the password. */
export type SavedConfig = SavedConfig_Serialize | SavedConfig_Deserialize;

/**  A `ConnectRequest` minus the password. */
export type SavedConfig_Deserialize =
    | ({
          kind: 'postgres';
      } & Server_Deserialize)
    | ({
          kind: 'mysql';
      } & Server_Deserialize)
    | { kind: 'sqlite'; path: string };

/**  A `ConnectRequest` minus the password. */
export type SavedConfig_Serialize =
    | ({
          kind: 'postgres';
      } & Server_Serialize)
    | ({
          kind: 'mysql';
      } & Server_Serialize)
    | { kind: 'sqlite'; path: string };

export type SavedConnection = SavedConnection_Serialize | SavedConnection_Deserialize;

export type SavedConnection_Deserialize = {
    id: string;
    label: string;
    config: SavedConfig_Deserialize;
};

export type SavedConnection_Serialize = {
    id: string;
    label: string;
    config: SavedConfig_Serialize;
};

export type Schema = {
    name: string;
    tables: Table[];
};

/**  Where a network database server is and who to sign in as. */
export type Server = Server_Serialize | Server_Deserialize;

export type ServerLogin = ServerLogin_Serialize | ServerLogin_Deserialize;

export type ServerLogin_Deserialize = {
    password: string;
} & Server_Deserialize;

export type ServerLogin_Serialize = {
    password: string;
} & Server_Serialize;

/**  Where a network database server is and who to sign in as. */
export type Server_Deserialize = {
    host: string;
    port: number;
    user: string;
    /**
     *  Empty means the server's default: for Postgres a database named after the user, for
     *  MySQL none (queries then name the database, as in `shop.orders`).
     */
    database: string;
    /**
     *  List every database on the server in the explorer, not just `database`. Missing means
     *  off, so connections saved before the option existed still load. (specta splits types with
     *  a defaulted field into `_Serialize`/`_Deserialize` copies; here both have the same shape.)
     */
    showAllDatabases?: boolean;
};

/**  Where a network database server is and who to sign in as. */
export type Server_Serialize = {
    host: string;
    port: number;
    user: string;
    /**
     *  Empty means the server's default: for Postgres a database named after the user, for
     *  MySQL none (queries then name the database, as in `shop.orders`).
     */
    database: string;
    /**
     *  List every database on the server in the explorer, not just `database`. Missing means
     *  off, so connections saved before the option existed still load. (specta splits types with
     *  a defaulted field into `_Serialize`/`_Deserialize` copies; here both have the same shape.)
     */
    showAllDatabases?: boolean;
};

export type Stage =
    | 'checking_runtime'
    | 'pulling_image'
    | 'creating_storage'
    | 'creating_container'
    | 'installing'
    | 'starting'
    | 'waiting_for_health'
    | 'creating_database'
    | 'initializing_sample_data'
    | 'validating'
    | 'registering_connection'
    | 'ready';

export type StageState =
    | 'running'
    | 'done'
    | 'skipped'
    | 'failed'
    /**  A line of output from the running stage (password-masked). */
    | 'output';

export type Table = {
    name: string;
    view: boolean;
};

export type Template = Template_Serialize | Template_Deserialize;

export type Template_Deserialize = {
    engine: Engine;
    name: string;
    description: string;
    /**  Empty for SQLite. */
    versions: VersionOption[];
    /**  `None` for SQLite. */
    defaultPort?: number | null;
    defaultUser: string;
    /**  MySQL and MariaDB have a separate root account; Postgres' user is the superuser. */
    hasRootPassword: boolean;
};

export type Template_Serialize = {
    engine: Engine;
    name: string;
    description: string;
    /**  Empty for SQLite. */
    versions: VersionOption[];
    /**  `None` for SQLite. */
    defaultPort: number | null;
    defaultUser: string;
    /**  MySQL and MariaDB have a separate root account; Postgres' user is the superuser. */
    hasRootPassword: boolean;
};

export type TestOutcome = {
    ok: boolean;
    message: string;
    /**  False when the password couldn't be recovered and has to be typed. */
    needsCredentials: boolean;
};

export type Verification = Verification_Serialize | Verification_Deserialize;

export type Verification_Deserialize = {
    intact: boolean;
    /**  Entries checked: all of them when intact, otherwise the ones before the break. */
    entries: number;
    /**  The first entry whose hash or link to the previous entry doesn't match. */
    brokenId?: number | null;
};

export type Verification_Serialize = {
    intact: boolean;
    /**  Entries checked: all of them when intact, otherwise the ones before the break. */
    entries: number;
    /**  The first entry whose hash or link to the previous entry doesn't match. */
    brokenId: number | null;
};

/**
 *  One pinned version of an engine. `id` is what the UI sends back; the image tag is exact, never
 *  `latest`, so every instance of a version starts from the same bits.
 */
export type VersionOption = {
    id: string;
    /**  The exact image tag, e.g. `17.11`. */
    tag: string;
};

/* Tauri Specta runtime */
type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

type EventEmitTo<T> = [T] extends [null]
    ? (target: __TAURI_EVENT.EventTarget | string) => Promise<void>
    : (target: __TAURI_EVENT.EventTarget | string, payload: T) => Promise<void>;

function makeEvent<TListen, TEmit = TListen>(name: string, serialize?: (payload: TEmit) => unknown, deserialize?: (payload: any) => TListen) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<TListen>) => (event: __TAURI_EVENT.Event<any>) =>
        cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: TEmit) => (serialize ? serialize(payload) : payload);

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) =>
            __TAURI_EVENT.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>,
    };

    const fn = (target: import('@tauri-apps/api/webview').Webview | import('@tauri-apps/api/window').Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) =>
            target.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>,
    });

    return Object.assign(fn, base);
}
